#[derive(Clone)]
struct GoldCase {
    id: String,
    connector: String,
    format: SourceFormat,
    input_json: String,
    expected: Json,
}

fn gold_bytes() -> Vec<u8> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("source_standard")
        .join("two-source-gold.json");
    fs::read(&path).unwrap_or_else(|error| panic!("read {}: {error}", path.display()))
}

fn gold_cases() -> Vec<GoldCase> {
    let bytes = gold_bytes();
    assert_eq!(
        Sha256Digest::of(&bytes).hex(),
        GOLD_SHA256,
        "the product gold copy is the frozen fixture"
    );
    let gold: Json = serde_json::from_slice(&bytes).expect("parse product gold copy");
    let cases = gold["cases"].as_array().expect("gold cases");
    assert_eq!(cases.len(), 24, "the frozen gold holds exactly 24 cases");
    cases
        .iter()
        .map(|case| {
            let connector = case["connector"]
                .as_str()
                .expect("case connector")
                .to_string();
            assert!(
                connector == "claude_code" || connector == "codex",
                "unexpected connector {connector}"
            );
            let format = match case["format"].as_str().expect("case format") {
                "jsonl" => SourceFormat::Jsonl,
                "json_document" => SourceFormat::JsonDocument,
                other => panic!("unknown source format {other}"),
            };
            GoldCase {
                id: case["id"].as_str().expect("case id").to_string(),
                connector,
                format,
                input_json: case["input_json"].as_str().expect("input_json").to_string(),
                expected: case["expected_standard"].clone(),
            }
        })
        .collect()
}

fn gold_index(cases: &[GoldCase]) -> BTreeMap<[u8; 32], GoldCase> {
    let mut index = BTreeMap::new();
    for case in cases {
        index.insert(key_for(case), case.clone());
    }
    index
}

fn key_for(case: &GoldCase) -> [u8; 32] {
    *verified_for(&case.id, &case.connector, case.format, &sealed_for(case))
        .input_key()
        .as_bytes()
}

fn sealed_for(case: &GoldCase) -> Vec<u8> {
    let mut bytes = case.input_json.clone().into_bytes();
    if case.format == SourceFormat::Jsonl {
        bytes.push(b'\n');
    }
    bytes
}

