fn verified_for(
    id: &str,
    connector: &str,
    format: SourceFormat,
    sealed: &[u8],
) -> VerifiedSourceInput {
    let context = context_value();
    let context_hex = context_digest(&context).expect("context digest").hex();
    let payload_hex = Sha256Digest::of(sealed).hex();
    let locator = format!(
        "{id}.{}",
        match format {
            SourceFormat::Jsonl => "jsonl",
            SourceFormat::JsonDocument => "json",
        }
    );
    let tuple = vec![
        Some("cass.source-input/2".into()),
        Some("C13_NAMESPACE".into()),
        Some(id.into()),
        Some(connector.into()),
        Some("/synthetic/c13".into()),
        Some(locator.clone()),
        Some("primary_session_log".into()),
        Some("local".into()),
        None,
        None,
        None,
        Some(context_hex),
        Some(payload_hex),
        Some("C13_NORMALIZER".into()),
        Some("C13_SAFETY".into()),
    ];
    let declaration = SourceInputDeclaration {
        identity_tuple: tuple,
        identity_namespace: "C13_NAMESPACE".into(),
        source_id: id.into(),
        connector: connector.into(),
        origin_kind: Some("local".into()),
        origin_host: None,
        origin_source_version: None,
        role: Some("primary_session_log".into()),
        platform: None,
        root_id: "/synthetic/c13".into(),
        relative_locator: locator,
        discovery: context.clone(),
        parser_context: context.clone(),
        sealed_ref: context,
        format,
        normalizer_id: "C13_NORMALIZER".into(),
        safety_contract_id: "C13_SAFETY".into(),
    };
    VerifiedSourceInput::verify(declaration, sealed, &safety())
        .expect("public verifier accepts the synthetic input")
        .0
}

/// A legal rich-information input: distinct host/profile and distinct lossless
/// trees, so the full page has to carry real material rather than defaults.
fn verified_rich(id: &str, connector: &str, sealed: &[u8]) -> VerifiedSourceInput {
    let discovery = LosslessSourceValue::parse(br#"{"fixture":"C13_DISCOVERY"}"#).expect("tree");
    let parser_context =
        LosslessSourceValue::parse(br#"{"fixture":"C13_PARSER_CONTEXT"}"#).expect("tree");
    let sealed_ref = LosslessSourceValue::parse(br#"{"fixture":"C13_SEALED_REF"}"#).expect("tree");
    let context_hex = context_digest(&parser_context)
        .expect("context digest")
        .hex();
    let payload_hex = Sha256Digest::of(sealed).hex();
    let locator = format!("{id}.jsonl");
    let tuple = vec![
        Some("cass.source-input/2".to_string()),
        Some("C13_NAMESPACE".to_string()),
        Some(id.to_string()),
        Some(connector.to_string()),
        Some("/synthetic/c13".to_string()),
        Some(locator.clone()),
        Some("primary_session_log".to_string()),
        Some("local".to_string()),
        Some("C13_HOST".to_string()),
        Some("C13_SOURCE_VERSION".to_string()),
        Some("linux".to_string()),
        Some(context_hex),
        Some(payload_hex),
        Some("C13_NORMALIZER".to_string()),
        Some("C13_SAFETY".to_string()),
    ];
    let declaration = SourceInputDeclaration {
        identity_tuple: tuple,
        identity_namespace: "C13_NAMESPACE".into(),
        source_id: id.into(),
        connector: connector.into(),
        origin_kind: Some("local".into()),
        origin_host: Some("C13_HOST".into()),
        origin_source_version: Some("C13_SOURCE_VERSION".into()),
        role: Some("primary_session_log".into()),
        platform: Some("linux".into()),
        root_id: "/synthetic/c13".into(),
        relative_locator: locator,
        discovery,
        parser_context,
        sealed_ref,
        format: SourceFormat::Jsonl,
        normalizer_id: "C13_NORMALIZER".into(),
        safety_contract_id: "C13_SAFETY".into(),
    };
    VerifiedSourceInput::verify(declaration, sealed, &safety())
        .expect("public verifier accepts the rich input")
        .0
}

fn frames_for(sealed: &[u8], format: SourceFormat) -> Vec<FramedSourceRecord> {
    let mut scan = FramingScan::new(sealed, format);
    let mut frames = Vec::new();
    while !scan.is_done() {
        frames.extend(scan.next_page(64).expect("scan page"));
    }
    frames
}

fn safe_tree(text: &str) -> LosslessSourceValue {
    LosslessSourceValue::parse(text.as_bytes()).expect("parse lossless source value")
}

fn tagged(value: &LosslessSourceValue) -> Vec<u8> {
    let mut bytes = Vec::new();
    value.write_tagged(&mut bytes).expect("tagged source bytes");
    bytes
}

fn tagged_opt(value: &Option<LosslessSourceValue>) -> Option<Vec<u8>> {
    value.as_ref().map(tagged)
}

/// The frozen gold records: one verified record per case with the parsed
/// original input as its safe value and the declared connector and format.
fn staged_gold(case: &GoldCase, sealed: &[u8]) -> Vec<VerifiedStagedRecord> {
    let frames = frames_for(sealed, case.format);
    assert_eq!(frames.len(), 1, "{}: one gold record", case.id);
    let frame = &frames[0];
    vec![VerifiedStagedRecord::from_frame(
        frame,
        Some(*frame.raw_sha256()),
        ParseState::Parsed,
        RecordMappingState::NoClaims,
        SafetyState::Preserved,
        None,
        Some(safe_tree(&case.input_json)),
        None,
    )]
}

/// One verified record with or without a retained safe value.
fn staged_variant(
    sealed: &[u8],
    format: SourceFormat,
    with_payload: bool,
) -> Vec<VerifiedStagedRecord> {
    frames_for(sealed, format)
        .iter()
        .map(|frame| {
            let locator = frame.locator();
            let safe = if with_payload {
                Some(safe_tree(
                    std::str::from_utf8(
                        &sealed[locator.byte_start as usize..locator.byte_end as usize],
                    )
                    .expect("utf8 record"),
                ))
            } else {
                None
            };
            VerifiedStagedRecord::from_frame(
                frame,
                Some(*frame.raw_sha256()),
                ParseState::Parsed,
                RecordMappingState::NoClaims,
                SafetyState::Preserved,
                None,
                safe,
                None,
            )
        })
        .collect()
}

fn mark_staged(tx: &Tx<'_>, input_id: i64, records: &[VerifiedStagedRecord]) {
    for record in records {
        let locator = record.locator();
        assert_eq!(
            tx.execute(
                "UPDATE source_records SET frame_state = 'staged'
                 WHERE input_id = ?1 AND ordinal = ?2 AND record_pointer = ?3",
                &[
                    Value::Integer(input_id),
                    Value::Blob(u64_be8(locator.ordinal).to_vec()),
                    Value::Text(locator.record_pointer.clone()),
                ],
            )
            .expect("frame state update"),
            1
        );
    }
}

fn library_of(tx: &Tx<'_>) -> String {
    tx.query_row_map(
        "SELECT value FROM meta WHERE key = 'library_identity'",
        &[],
        |row| row.get_typed(0),
    )
    .expect("library identity")
}

fn header_of(tx: &Tx<'_>, input_id: i64) -> Vec<u8> {
    tx.query_row_map(
        "SELECT expected_manifest_bin FROM source_inputs WHERE id = ?1",
        &[Value::Integer(input_id)],
        |row| row.get_typed(0),
    )
    .expect("expected manifest header")
}

fn finish_from(
    manifest: &coding_agent_search::storage::source_facts::VerifiedExpectedManifest,
) -> VerifiedFinish {
    VerifiedFinish {
        content_digest: *manifest.sealed_sha256(),
        bytes_read: manifest.byte_len(),
        records_seen: manifest.records(),
        blank_lines: manifest.blank_lines(),
        parse_failed: 0,
        mapping_diagnostics: 0,
        unprocessed_ranges: vec![],
        reached_eof: true,
    }
}

fn activate(
    tx: &Tx<'_>,
    input: &VerifiedSourceInput,
    input_id: i64,
    disposition: ProjectionDisposition,
    terminal: TerminalState,
) {
    let (records_root, claims_root) =
        source_a_roots_in_tx(tx, input.input_key(), input_id).expect("A roots");
    let header = header_of(tx, input_id);
    let (manifest, _) = decode_expected_manifest_header(&header).expect("header");
    let finish = finish_from(&manifest);
    let (normalizer_id, safety_contract_id): (String, String) = tx
        .query_row_map(
            "SELECT normalizer_id, safety_contract_id FROM source_inputs WHERE id = ?1",
            &[Value::Integer(input_id)],
            |row| Ok((row.get_typed(0)?, row.get_typed(1)?)),
        )
        .expect("stored profile");
    let request = SourceActivationRequest {
        input_key: *input.input_key(),
        library_identity: library_of(tx),
        normalizer_id,
        safety_contract_id,
        expected_manifest_digest: Sha256Digest::of(&header),
        finish,
        projection_disposition: disposition,
        source_semantic_records_root: records_root,
        claims_root,
        requested_terminal: terminal,
    };
    activate_source_input_in_tx(tx, &request, &manifest).expect("activation");
}

/// Publish one input in its own transaction and close the writer again.
fn publish(
    db: &Path,
    input: &VerifiedSourceInput,
    records: &[VerifiedStagedRecord],
    disposition: ProjectionDisposition,
    terminal: TerminalState,
) {
    let storage = FrankenStorage::open(db).expect("open schema9");
    let tx = storage
        .raw()
        .transaction_with_mode(TxMode::Immediate)
        .expect("tx");
    let staged = stage_source_records_in_tx(&tx, input, records).expect("stage");
    mark_staged(&tx, staged.input_id, records);
    activate(&tx, input, staged.input_id, disposition, terminal);
    tx.commit().expect("commit");
    storage.close().expect("close");
}

fn publish_gold_case(db: &Path, case: &GoldCase) -> Sha256Digest {
    let sealed = sealed_for(case);
    let input = verified_for(&case.id, &case.connector, case.format, &sealed);
    let records = staged_gold(case, &sealed);
    publish(
        db,
        &input,
        &records,
        ProjectionDisposition::WholeInputRejected,
        TerminalState::Failed,
    );
    *input.input_key()
}

fn publish_empty(db: &Path, id: &str) -> Sha256Digest {
    let input = verified_for(id, "claude_code", SourceFormat::Jsonl, b"");
    publish(
        db,
        &input,
        &[],
        ProjectionDisposition::Ready,
        TerminalState::Complete,
    );
    *input.input_key()
}

fn corrupt(db: &Path, sql: &str, params: &[Value]) {
    let storage = FrankenStorage::open(db).expect("corruption writer");
    storage
        .raw()
        .execute(sql, params)
        .expect("corruption update");
    storage.close().expect("close");
}

fn corrupt_batch(db: &Path, sql: &str) {
    let storage = FrankenStorage::open(db).expect("corruption writer");
    storage.raw().execute_batch(sql).expect("corruption batch");
    storage.close().expect("close");
}

fn build_legacy(db: &Path, ddl: &str, version: i64) {
    let mut guard = open_test_writer(db, Profile::Production).expect("legacy writer");
    {
        let conn = guard.storage().raw();
        conn.execute_batch(ddl).expect("historical ddl");
        conn.execute_batch(&format!("PRAGMA user_version = {version};"))
            .expect("version");
        conn.execute_batch("PRAGMA journal_mode = DELETE;")
            .expect("non-wal fixture");
    }
    guard.mark_committed();
}

fn file_digest(db: &Path) -> Sha256Digest {
    Sha256Digest::of(&fs::read(db).expect("read db"))
}

