fn read_raw(
    reader: &SourceFactsReader,
    filter: &SourceFactsFilter,
    limits: SourceFactsPageLimits,
) -> Vec<RawSourceFactsPage> {
    let mut pages = Vec::new();
    let mut cursor: Option<String> = None;
    loop {
        let page = reader
            .read_raw_source_facts(filter, cursor.as_deref(), limits)
            .expect("raw page");
        cursor = page.next_cursor.clone();
        pages.push(page);
        if cursor.is_none() {
            return pages;
        }
    }
}

fn read_full(
    reader: &SourceFactsReader,
    filter: &SourceFactsFilter,
    limits: SourceFactsPageLimits,
) -> Vec<SourceFactsPage> {
    let mut pages = Vec::new();
    let mut cursor: Option<String> = None;
    loop {
        let page = reader
            .read_source_facts(filter, cursor.as_deref(), limits)
            .expect("full page");
        cursor = page.next_cursor.clone();
        pages.push(page);
        if cursor.is_none() {
            return pages;
        }
    }
}

fn assert_same_input(full: &SourceFactsInput, raw: &SourceFactsInput) {
    assert_eq!(full.input_key, raw.input_key);
    assert_eq!(full.identity_tuple, raw.identity_tuple);
    assert_eq!(full.identity_namespace, raw.identity_namespace);
    assert_eq!(full.source_id, raw.source_id);
    assert_eq!(full.connector, raw.connector);
    assert_eq!(full.root_id, raw.root_id);
    assert_eq!(full.relative_locator, raw.relative_locator);
    assert_eq!(full.origin_kind, raw.origin_kind);
    assert_eq!(full.origin_host, raw.origin_host);
    assert_eq!(full.origin_source_version, raw.origin_source_version);
    assert_eq!(full.role, raw.role);
    assert_eq!(full.platform, raw.platform);
    assert_eq!(tagged(&full.discovery), tagged(&raw.discovery));
    assert_eq!(tagged(&full.parser_context), tagged(&raw.parser_context));
    assert_eq!(tagged(&full.sealed_ref), tagged(&raw.sealed_ref));
    assert_eq!(full.context_digest, raw.context_digest);
    assert_eq!(full.sealed_sha256, raw.sealed_sha256);
    assert_eq!(full.byte_len, raw.byte_len);
    assert_eq!(full.format, raw.format);
    assert_eq!(
        full.expected_manifest.manifest,
        raw.expected_manifest.manifest
    );
    assert_eq!(full.expected_manifest.safety, raw.expected_manifest.safety);
    assert_eq!(full.normalizer_id, raw.normalizer_id);
    assert_eq!(full.safety_contract_id, raw.safety_contract_id);
    assert_eq!(full.state, raw.state);
    assert_eq!(full.expected_records, raw.expected_records);
    assert_eq!(full.expected_blank_lines, raw.expected_blank_lines);
    assert_eq!(full.observed_records, raw.observed_records);
    assert_eq!(full.observed_blank_lines, raw.observed_blank_lines);
    assert_eq!(full.unprocessed_ranges, raw.unprocessed_ranges);
    assert_eq!(full.attempt_history, raw.attempt_history);
    assert_eq!(full.activation_request_hash, raw.activation_request_hash);
    assert_eq!(full.receipt_key, raw.receipt_key);
    assert_eq!(
        full.applied_content_generation,
        raw.applied_content_generation
    );
}

fn assert_same_link(full: &SourceFactsRecordLink, raw: &SourceFactsRecordLink) {
    assert_eq!(full.claim, raw.claim);
    assert_eq!(full.original_installation, raw.original_installation);
    assert_eq!(full.binding_digest, raw.binding_digest);
    assert_eq!(full.authority, raw.authority);
    assert_eq!(full.message_id, raw.message_id);
}

fn assert_same_record(full: &RawSourceFactsRecord, raw: &RawSourceFactsRecord) {
    assert_eq!(full.input_key, raw.input_key);
    assert_eq!(full.ordinal, raw.ordinal);
    assert_eq!(full.record_pointer, raw.record_pointer);
    assert_eq!(full.byte_start, raw.byte_start);
    assert_eq!(full.byte_end, raw.byte_end);
    assert_eq!(full.record_byte_len, raw.record_byte_len);
    assert_eq!(
        full.expected_source_record_sha256,
        raw.expected_source_record_sha256
    );
    assert_eq!(
        full.observed_source_record_sha256,
        raw.observed_source_record_sha256
    );
    assert_eq!(full.frame_state, raw.frame_state);
    assert_eq!(full.parse_state, raw.parse_state);
    assert_eq!(full.record_mapping_state, raw.record_mapping_state);
    assert_eq!(full.safety_state, raw.safety_state);
    assert_eq!(full.retention_state, raw.retention_state);
    assert_eq!(full.codec, raw.codec);
    assert_eq!(full.payload, raw.payload);
    assert_eq!(full.payload_sha256, raw.payload_sha256);
    assert_eq!(full.safe_value_hash, raw.safe_value_hash);
    assert_eq!(tagged_opt(&full.safe_value), tagged_opt(&raw.safe_value));
    assert_eq!(tagged_opt(&full.native_ids), tagged_opt(&raw.native_ids));
    assert_eq!(full.diagnostics, raw.diagnostics);
    assert_eq!(full.links.len(), raw.links.len());
    for (full_link, raw_link) in full.links.iter().zip(raw.links.iter()) {
        assert_same_link(full_link, raw_link);
    }
}

fn assert_same_page(full: &SourceFactsPage, raw: &RawSourceFactsPage) {
    assert_eq!(full.reader_version, raw.reader_version);
    assert_eq!(full.library_identity, raw.library_identity);
    assert_eq!(full.source_facts_revision, raw.source_facts_revision);
    assert_eq!(full.filter_digest, raw.filter_digest);
    assert_eq!(full.oversized_records, raw.oversized_records);
    assert_eq!(full.next_cursor, raw.next_cursor);
    assert_eq!(full.inputs.len(), raw.inputs.len());
    for (full_input, raw_input) in full.inputs.iter().zip(raw.inputs.iter()) {
        assert_same_input(full_input, raw_input);
    }
    assert_eq!(full.records.len(), raw.records.len());
    for (full_record, raw_record) in full.records.iter().zip(raw.records.iter()) {
        assert_same_record(&full_record.raw, raw_record);
    }
}

fn typed_equal(left: &Json, right: &Json) -> bool {
    match (left, right) {
        (Json::Null, Json::Null) => true,
        (Json::Bool(left), Json::Bool(right)) => left == right,
        (Json::Number(left), Json::Number(right)) => left == right,
        (Json::String(left), Json::String(right)) => left == right,
        (Json::Array(left), Json::Array(right)) => {
            left.len() == right.len()
                && left
                    .iter()
                    .zip(right.iter())
                    .all(|(left, right)| typed_equal(left, right))
        }
        (Json::Object(left), Json::Object(right)) => {
            left.len() == right.len()
                && left.iter().all(|(key, value)| {
                    right
                        .get(key)
                        .is_some_and(|expected| typed_equal(value, expected))
                })
        }
        _ => false,
    }
}

fn assert_gold_standard(record: &SourceFactsRecord, case: &GoldCase) {
    let standard = record
        .standard
        .as_ref()
        .unwrap_or_else(|| panic!("{}: standard facts are missing", case.id));
    let actual = serde_json::to_value(standard).expect("serialize StandardFacts");
    assert!(
        typed_equal(&actual, &case.expected),
        "{} differs\nexpected: {}\nactual: {}",
        case.id,
        serde_json::to_string_pretty(&case.expected).expect("pretty expected"),
        serde_json::to_string_pretty(&actual).expect("pretty actual")
    );
}

fn write_mapper_result(results: &[Json]) {
    let Some(path) = std::env::var_os("CASS_MAPPER_RESULT") else {
        return;
    };
    let path = PathBuf::from(path);
    let temporary = path.with_extension("json.tmp");
    let bytes = serde_json::to_vec(results).expect("serialize mapper results");
    fs::write(&temporary, bytes).expect("write temporary mapper result");
    fs::rename(&temporary, &path).expect("replace mapper result");
}

fn reason(error: &SourceFactsReadError) -> String {
    error
        .detail()
        .get("reason")
        .and_then(Json::as_str)
        .expect("reason")
        .to_string()
}

fn assert_same_error(
    full: &SourceFactsReadError,
    raw: &SourceFactsReadError,
    kind: SourceFactsReadErrorCode,
    expected_reason: &str,
) {
    assert_eq!(full.kind(), kind);
    assert_eq!(raw.kind(), kind);
    assert_eq!(full.code(), raw.code());
    assert_eq!(full.detail(), raw.detail());
    assert_eq!(reason(full), expected_reason);
}

// ---------------------------------------------------------------------------
// e01: the original 24 gold records through a real close/reopen
// ---------------------------------------------------------------------------

#[test]
fn e01_two_source_gold24_reopen() {
    let (_dir, db) = db_path("e01");
    let cases = gold_cases();
    assert_eq!(
        cases
            .iter()
            .filter(|case| case.connector == "claude_code")
            .count(),
        10,
        "the gold holds exactly ten Claude records"
    );
    assert_eq!(
        cases
            .iter()
            .filter(|case| case.connector == "codex")
            .count(),
        14,
        "the gold holds exactly fourteen Codex records"
    );

    for case in &cases {
        publish_gold_case(&db, case);
    }

    let expected_by_key = gold_index(&cases);
    let reader = SourceFactsReader::open(&db).expect("fresh read-only handle");
    let filter = SourceFactsFilter {
        scope: SourceFactsScope::AllSource,
        ..Default::default()
    };
    let mut cursor: Option<String> = None;
    let mut seen: BTreeSet<[u8; 32]> = BTreeSet::new();
    let mut results = Vec::new();
    loop {
        let page = reader
            .read_source_facts(&filter, cursor.as_deref(), SourceFactsPageLimits::default())
            .expect("full page after reopen");
        assert_eq!(page.reader_version, 2);
        for record in &page.records {
            let case = expected_by_key
                .get(record.raw.input_key.as_bytes())
                .unwrap_or_else(|| panic!("record input key is not a gold case"));
            assert!(
                seen.insert(*record.raw.input_key.as_bytes()),
                "{}: record appears twice",
                case.id
            );
            let safe = record
                .raw
                .safe_value
                .as_ref()
                .unwrap_or_else(|| panic!("{}: safe value missing", case.id));
            assert_eq!(
                tagged(safe),
                tagged(&safe_tree(&case.input_json)),
                "{}: tagged source bytes differ",
                case.id
            );
            assert_gold_standard(record, case);
            let actual = serde_json::to_value(record.standard.as_ref().expect("standard"))
                .expect("serialize StandardFacts");
            results.push(json!({"id": case.id, "actual_standard": actual}));
        }
        cursor = page.next_cursor;
        if cursor.is_none() {
            break;
        }
    }
    assert_eq!(seen.len(), 24, "every gold record is read exactly once");
    assert_eq!(results.len(), 24, "exactly 24 complete outputs");
    write_mapper_result(&results);
}

// ---------------------------------------------------------------------------
// e02: every raw page member under three page limits, plus empty headers
// ---------------------------------------------------------------------------

#[test]
fn e02_full_raw_pages_and_empty_headers() {
    let (_dir, db) = db_path("e02");
    let cases = gold_cases();
    for case in &cases {
        publish_gold_case(&db, case);
    }
    publish_empty(&db, "C13_EMPTY_A");
    publish_empty(&db, "C13_EMPTY_B");

    let expected_by_key = gold_index(&cases);
    let reader = SourceFactsReader::open(&db).expect("read-only handle");
    let filter = SourceFactsFilter {
        scope: SourceFactsScope::AllSource,
        ..Default::default()
    };

    for (max_records, target_bytes, expected_pages, expected_oversized) in [
        (2_usize, 8_388_608_u64, 13_usize, 0_u64),
        (64, 20, 24, 24),
        (64, 8_388_608, 1, 0),
    ] {
        let limits = SourceFactsPageLimits {
            max_records,
            target_bytes,
        };
        let raw_pages = read_raw(&reader, &filter, limits);
        let full_pages = read_full(&reader, &filter, limits);
        assert_eq!(
            full_pages.len(),
            expected_pages,
            "page count for {max_records}/{target_bytes}"
        );
        assert_eq!(raw_pages.len(), full_pages.len());
        let mut record_keys = BTreeSet::new();
        let mut header_keys = BTreeSet::new();
        let mut oversized = 0_u64;
        for (index, (full, raw)) in full_pages.iter().zip(raw_pages.iter()).enumerate() {
            assert_same_page(full, raw);
            oversized += full.oversized_records;
            for input in &full.inputs {
                header_keys.insert(*input.input_key.as_bytes());
            }
            for record in &full.records {
                assert!(
                    record_keys.insert(*record.raw.input_key.as_bytes()),
                    "duplicate record input key on page {index}"
                );
                let case = expected_by_key
                    .get(record.raw.input_key.as_bytes())
                    .expect("gold case for the record");
                assert_gold_standard(record, case);
            }
        }
        assert_eq!(record_keys.len(), 24);
        assert_eq!(header_keys.len(), 26, "24 gold inputs plus two empty ones");
        assert_eq!(
            oversized, expected_oversized,
            "summed oversized records for {max_records}/{target_bytes}"
        );
        assert!(
            full_pages.last().expect("pages").next_cursor.is_none(),
            "the traversal ends at the terminal cursor"
        );
    }

    // A raw page cursor continues a full page and vice versa: both APIs share
    // the one frozen v2 cursor.
    let limits = SourceFactsPageLimits {
        max_records: 2,
        target_bytes: 8_388_608,
    };
    let raw_first = reader
        .read_raw_source_facts(&filter, None, limits)
        .expect("raw first page");
    let cursor = raw_first.next_cursor.clone().expect("raw cursor");
    let raw_next = reader
        .read_raw_source_facts(&filter, Some(&cursor), limits)
        .expect("raw next page");
    let full_next = reader
        .read_source_facts(&filter, Some(&cursor), limits)
        .expect("full after raw cursor");
    assert_same_page(&full_next, &raw_next);

    let full_first = reader
        .read_source_facts(&filter, None, limits)
        .expect("full first page");
    let cursor = full_first.next_cursor.clone().expect("full cursor");
    let full_next = reader
        .read_source_facts(&filter, Some(&cursor), limits)
        .expect("full next page");
    let raw_next = reader
        .read_raw_source_facts(&filter, Some(&cursor), limits)
        .expect("raw after full cursor");
    assert_same_page(&full_next, &raw_next);
}

// ---------------------------------------------------------------------------
// e03: no payload and unmapped connectors keep the raw facts only
// ---------------------------------------------------------------------------

#[test]
fn e03_missing_payload_and_unmapped_connectors() {
    let (_dir, db) = db_path("e03");
    let sealed = b"{\"type\":\"unknown\"}\n";
    let variants: [(&str, &str, bool); 4] = [
        ("C13_CLAUDE_ABSENT", "claude_code", false),
        ("C13_CODEX_ABSENT", "codex", false),
        ("C13_OTHER_PRESENT", "other_source", true),
        ("C13_ALIAS_PRESENT", "claude", true),
    ];
    let mut expected = BTreeMap::new();
    for (id, connector, payload) in variants {
        let input = verified_for(id, connector, SourceFormat::Jsonl, sealed);
        let records = staged_variant(sealed, SourceFormat::Jsonl, payload);
        publish(
            &db,
            &input,
            &records,
            ProjectionDisposition::WholeInputRejected,
            TerminalState::Failed,
        );
        expected.insert(*input.input_key().as_bytes(), (connector, payload));
    }

    let reader = SourceFactsReader::open(&db).expect("read-only handle");
    let filter = SourceFactsFilter {
        scope: SourceFactsScope::AllSource,
        ..Default::default()
    };
    let pages = read_full(&reader, &filter, SourceFactsPageLimits::default());
    let records: Vec<&SourceFactsRecord> =
        pages.iter().flat_map(|page| page.records.iter()).collect();
    assert_eq!(records.len(), 4);
    let mut seen = BTreeSet::new();
    for record in records {
        let (connector, payload) = expected
            .get(record.raw.input_key.as_bytes())
            .unwrap_or_else(|| panic!("unexpected record input"));
        assert!(seen.insert(*record.raw.input_key.as_bytes()));
        assert!(
            record.standard.is_none(),
            "{connector}: no standard facts are fabricated"
        );
        assert!(
            !record.raw.frame_state.is_empty()
                && !record.raw.parse_state.is_empty()
                && !record.raw.record_mapping_state.is_empty()
                && !record.raw.safety_state.is_empty()
                && !record.raw.retention_state.is_empty(),
            "{connector}: record state is retained"
        );
        assert!(record.raw.links.is_empty(), "{connector}: no links");
        match payload {
            true => {
                assert_eq!(
                    record.raw.retention_state, "payload_present",
                    "{connector}: the payload is retained"
                );
                let safe = record
                    .raw
                    .safe_value
                    .as_ref()
                    .unwrap_or_else(|| panic!("{connector}: safe value missing"));
                assert_eq!(tagged(safe), tagged(&safe_tree("{\"type\":\"unknown\"}")));
                assert!(record.raw.payload.is_some());
                assert!(record.raw.codec.is_some());
                assert!(record.raw.safe_value_hash.is_some());
            }
            false => {
                assert_eq!(
                    record.raw.retention_state, "payload_absent",
                    "{connector}: no payload is fabricated"
                );
                assert!(record.raw.payload.is_none());
                assert!(record.raw.payload_sha256.is_none());
                assert!(record.raw.codec.is_none());
                assert!(record.raw.safe_value_hash.is_none());
                assert!(record.raw.safe_value.is_none());
            }
        }
    }
    assert_eq!(seen.len(), 4);
}

