fn seed_conversation(tx: &Tx<'_>) {
    tx.execute_batch(
        "INSERT OR IGNORE INTO agents(id,slug,name,kind,created_at,updated_at) \
             VALUES(1,'claude','Claude','agent',0,0);\
         INSERT OR IGNORE INTO conversations(id,agent_id,source_id,source_path,identity_host) \
             VALUES(1,1,'local','/synthetic/c13-canonical/session.jsonl','local');\
         INSERT OR IGNORE INTO messages(id,conversation_id,idx,role,content) \
             VALUES(7,1,0,'user','hello');",
    )
    .expect("seed conversation");
}

fn canonical_claim(key: &Sha256Digest, ordinal: u64) -> SourceClaim {
    SourceClaim {
        input_key: *key,
        record_ordinal: ordinal,
        record_pointer: String::new(),
        conversation_ordinal: Some(0),
        final_message_idx: Some(0),
        positions: vec![],
        projection_pointer: Some("/messages/0".into()),
        evidence_kind: EvidenceKind::Prose,
        mapping_state: ClaimMappingState::Canonical,
    }
}

fn standalone_claim(key: &Sha256Digest, ordinal: u64) -> SourceClaim {
    SourceClaim {
        input_key: *key,
        record_ordinal: ordinal,
        record_pointer: String::new(),
        conversation_ordinal: None,
        final_message_idx: None,
        positions: vec![],
        projection_pointer: None,
        evidence_kind: EvidenceKind::NoMessage,
        mapping_state: ClaimMappingState::Standalone,
    }
}

fn canonical_installation(digest: Sha256Digest, message_id: i64) -> OriginalInstallation {
    OriginalInstallation {
        semantic_request_digest: digest,
        class: InstallationClass::CanonicalBound,
        binding: Some(OriginalBinding {
            outcome: OriginalBindingOutcome::AcceptedNew,
            original_conversation_id: 1,
            original_message_id: message_id,
            stored_idx: 0,
            stored_merge_fingerprint: MergeFingerprint {
                idx: 0,
                created_at: Some(1),
                role: "User".into(),
                author: None,
                content_blake3_hex: "ab".repeat(32),
            },
            safe_content_sha256: Sha256Digest::of(b"hello"),
            extra_storage_kind: ExtraStorageKind::Null,
            extra_json_sha256: None,
            extra_bin_sha256: None,
            extra_semantic_digest: None,
            excluded_semantic_digest: None,
            conversation_identity_digest: Sha256Digest::of(b"identity"),
        }),
        rejection: None,
        reason: None,
    }
}

fn standalone_installation(digest: Sha256Digest) -> OriginalInstallation {
    OriginalInstallation {
        semantic_request_digest: digest,
        class: InstallationClass::StandaloneNoBinding,
        binding: None,
        rejection: None,
        reason: None,
    }
}

#[test]
fn e04_link_scope_and_raw_evidence() {
    let (_dir, db) = db_path("e04");
    let cases = gold_cases();
    let by_id: BTreeMap<&str, &GoldCase> =
        cases.iter().map(|case| (case.id.as_str(), case)).collect();
    let first = by_id["claude-identity-time"];
    let second = by_id["claude-unknown"];

    let sealed = format!(
        "{}\n{}\n",
        first.input_json.trim_end_matches('\n'),
        second.input_json.trim_end_matches('\n')
    )
    .into_bytes();
    let input = verified_rich("C13_LINKED", "claude_code", &sealed);
    let key = *input.input_key();
    let frames = frames_for(&sealed, SourceFormat::Jsonl);
    assert_eq!(frames.len(), 2, "one input holds exactly two records");
    let records: Vec<VerifiedStagedRecord> = frames
        .iter()
        .enumerate()
        .map(|(index, frame)| {
            let locator = frame.locator();
            let text = std::str::from_utf8(
                &sealed[locator.byte_start as usize..locator.byte_end as usize],
            )
            .expect("utf8 record");
            let native_ids = if index == 0 {
                Some(LosslessSourceValue::parse(br#"{"native":"C13"}"#).expect("native"))
            } else {
                None
            };
            let diagnostics = if index == 0 {
                Some(vec![SafeDiagnostic {
                    code: "C13_DIAG".into(),
                    detail: Some("kept".into()),
                    offset: Some(0),
                    position: None,
                }])
            } else {
                None
            };
            VerifiedStagedRecord::from_frame(
                frame,
                Some(*frame.raw_sha256()),
                ParseState::Parsed,
                if index == 0 {
                    RecordMappingState::Mixed
                } else {
                    RecordMappingState::NoClaims
                },
                SafetyState::Preserved,
                native_ids,
                Some(safe_tree(text)),
                diagnostics,
            )
        })
        .collect();

    let storage = FrankenStorage::open(&db).expect("open schema9");
    let tx = storage
        .raw()
        .transaction_with_mode(TxMode::Immediate)
        .expect("tx");
    let staged = stage_source_records_in_tx(&tx, &input, &records).expect("stage");
    mark_staged(&tx, staged.input_id, &records);
    seed_conversation(&tx);

    let claims = vec![canonical_claim(&key, 1), standalone_claim(&key, 1)];
    install_source_links_in_tx(
        &tx,
        staged.input_id,
        &claims
            .iter()
            .map(|claim| ClaimLinkInstall {
                claim: claim.clone(),
                installation: None,
            })
            .collect::<Vec<_>>(),
    )
    .expect("pending links");

    let header = header_of(&tx, staged.input_id);
    let (manifest, _) = decode_expected_manifest_header(&header).expect("header");
    let (records_root, claims_root) =
        source_a_roots_in_tx(&tx, &key, staged.input_id).expect("A roots");
    let finish = finish_from(&manifest);
    let digest = semantic_request_digest(
        &key,
        &Sha256Digest::of(&header),
        manifest.sealed_sha256(),
        manifest.byte_len(),
        manifest.format().as_str(),
        "C13_NORMALIZER",
        "C13_SAFETY",
        &finish,
        ProjectionDisposition::Ready,
        &records_root,
        &claims_root,
    );
    let installations = vec![
        canonical_installation(digest, 7),
        standalone_installation(digest),
    ];
    install_source_links_in_tx(
        &tx,
        staged.input_id,
        &claims
            .iter()
            .zip(installations.iter())
            .map(|(claim, installation)| ClaimLinkInstall {
                claim: claim.clone(),
                installation: Some(installation.clone()),
            })
            .collect::<Vec<_>>(),
    )
    .expect("installed links");
    let request = SourceActivationRequest {
        input_key: key,
        library_identity: library_of(&tx),
        normalizer_id: "C13_NORMALIZER".into(),
        safety_contract_id: "C13_SAFETY".into(),
        expected_manifest_digest: Sha256Digest::of(&header),
        finish,
        projection_disposition: ProjectionDisposition::Ready,
        source_semantic_records_root: records_root,
        claims_root,
        requested_terminal: TerminalState::Complete,
    };
    activate_source_input_in_tx(&tx, &request, &manifest).expect("activation");
    tx.commit().expect("commit");
    storage.close().expect("close");

    let reader = SourceFactsReader::open(&db).expect("read-only handle");
    let raw_pages = read_raw(
        &reader,
        &SourceFactsFilter {
            scope: SourceFactsScope::AllSource,
            ..Default::default()
        },
        SourceFactsPageLimits::default(),
    );
    let all_raw = raw_pages.first().expect("raw page");

    let scopes = [
        (SourceFactsScope::AllSource, vec![1_u64, 2]),
        (SourceFactsScope::Analysis, vec![1]),
        (SourceFactsScope::HistoryUnresolved, vec![2]),
    ];
    for (scope, expected_ordinals) in scopes {
        let filter = SourceFactsFilter {
            scope,
            input_keys: vec![key],
            ..Default::default()
        };
        let pages = read_full(&reader, &filter, SourceFactsPageLimits::default());
        let raws = read_raw(&reader, &filter, SourceFactsPageLimits::default());
        assert_eq!(
            pages.len(),
            raws.len(),
            "{}: full and raw page counts",
            scope.as_str()
        );
        for (full, raw) in pages.iter().zip(raws.iter()) {
            assert_same_page(full, raw);
        }
        let records: Vec<&SourceFactsRecord> =
            pages.iter().flat_map(|page| page.records.iter()).collect();
        let actual: Vec<u64> = records.iter().map(|record| record.raw.ordinal).collect();
        assert_eq!(actual, expected_ordinals, "{}", scope.as_str());
        assert_eq!(
            raws.iter().map(|page| page.records.len()).sum::<usize>(),
            expected_ordinals.len()
        );
        for record in &records {
            let expected = if record.raw.ordinal == 1 {
                first
            } else {
                second
            };
            assert_gold_standard(record, expected);
            assert_eq!(record.raw.input_key, key);
        }
        if scope == SourceFactsScope::AllSource {
            // The rich header and optional record material survive verbatim.
            let raw_input = all_raw.inputs.first().expect("raw input header");
            assert_eq!(raw_input.origin_host.as_deref(), Some("C13_HOST"));
            assert_eq!(raw_input.platform.as_deref(), Some("linux"));
        }
    }

    let analysis = read_full(
        &reader,
        &SourceFactsFilter {
            scope: SourceFactsScope::Analysis,
            input_keys: vec![key],
            ..Default::default()
        },
        SourceFactsPageLimits::default(),
    );
    let record = analysis
        .iter()
        .flat_map(|page| page.records.iter())
        .find(|record| record.raw.ordinal == 1)
        .expect("canonical record");
    assert_eq!(record.raw.links.len(), 2, "two links on the first record");
    let canonical = record
        .raw
        .links
        .iter()
        .find(|link| link.authority.as_deref() == Some("canonical"))
        .expect("canonical link");
    let standalone = record
        .raw
        .links
        .iter()
        .find(|link| link.authority.as_deref() == Some("standalone"))
        .expect("standalone link");
    let canonical_claim = canonical_claim(&key, 1);
    let standalone_claim = standalone_claim(&key, 1);
    assert_eq!(canonical.claim, canonical_claim);
    assert_eq!(standalone.claim, standalone_claim);
    let installed_canonical = canonical_installation(digest, 7);
    let installed_standalone = standalone_installation(digest);
    assert_eq!(
        canonical.original_installation.as_ref(),
        Some(&installed_canonical)
    );
    assert_eq!(
        standalone.original_installation.as_ref(),
        Some(&installed_standalone)
    );
    assert_eq!(
        canonical.binding_digest,
        binding_digest(&canonical_claim, &installed_canonical)
    );
    assert_eq!(
        standalone.binding_digest,
        binding_digest(&standalone_claim, &installed_standalone)
    );
    assert_eq!(canonical.message_id, Some(7));
    assert_eq!(standalone.message_id, None);
    assert_eq!(
        tagged(record.raw.native_ids.as_ref().expect("native ids")),
        tagged(&LosslessSourceValue::parse(br#"{"native":"C13"}"#).expect("native"))
    );
    assert_eq!(
        record.raw.diagnostics,
        Some(DiagnosticsEnvelope {
            version: SOURCE_ENVELOPE_VERSION,
            domain: SOURCE_DIAGNOSTICS_DOMAIN.into(),
            items: vec![SafeDiagnostic {
                code: "C13_DIAG".into(),
                detail: Some("kept".into()),
                offset: Some(0),
                position: None,
            }],
        })
    );
}

// ---------------------------------------------------------------------------
// e05: existing refusals, read-only archives and no swallowed errors
// ---------------------------------------------------------------------------

#[test]
fn e05_existing_refusals_and_readonly() {
    for (tag, ddl, version) in [
        ("e05-schema7", SCHEMA7_DDL, 7_i64),
        ("e05-schema8", SCHEMA8_DDL, 8),
    ] {
        let (_dir, db) = db_path(tag);
        build_legacy(&db, ddl, version);
        let before = file_digest(&db);
        let error = SourceFactsReader::open(&db).expect_err("legacy archive refused");
        assert_eq!(
            error.kind(),
            SourceFactsReadErrorCode::SourceFactsUnavailable
        );
        assert_eq!(reason(&error), "source_facts_unavailable");
        assert_eq!(file_digest(&db), before, "the archive is not written");
        assert!(
            !PathBuf::from(format!("{}-wal", db.display())).exists(),
            "no sidecar is created"
        );
    }

    let (_dir, base) = db_path("e05-base");
    let sealed = b"{\"type\":\"unknown\"}\n";
    let input = verified_for("C13_E05", "claude_code", SourceFormat::Jsonl, sealed);
    let key = *input.input_key();
    let records = staged_variant(sealed, SourceFormat::Jsonl, true);
    publish(
        &base,
        &input,
        &records,
        ProjectionDisposition::WholeInputRejected,
        TerminalState::Failed,
    );
    let filter = SourceFactsFilter {
        scope: SourceFactsScope::AllSource,
        input_keys: vec![key],
        ..Default::default()
    };
    let reader = SourceFactsReader::open(&base).expect("normal side");
    reader
        .read_raw_source_facts(&filter, None, SourceFactsPageLimits::default())
        .expect("normal raw side");
    reader
        .read_source_facts(&filter, None, SourceFactsPageLimits::default())
        .expect("normal full side");
    drop(reader);

    for limits in [
        SourceFactsPageLimits {
            max_records: 0,
            target_bytes: 8_388_608,
        },
        SourceFactsPageLimits {
            max_records: 64,
            target_bytes: 0,
        },
    ] {
        let reader = SourceFactsReader::open(&base).expect("reader");
        let raw_error = reader
            .read_raw_source_facts(&filter, None, limits)
            .expect_err("zero limit");
        let full_error = reader
            .read_source_facts(&filter, None, limits)
            .expect_err("zero limit");
        assert_same_error(
            &full_error,
            &raw_error,
            SourceFactsReadErrorCode::InvalidCursor,
            "invalid_page_limits",
        );
    }

    let cases = [
        (
            "unknown codec",
            "PRAGMA ignore_check_constraints = ON; UPDATE source_records SET codec = 'mystery/9'; PRAGMA ignore_check_constraints = OFF",
            "codec_invalid",
            Some("unsupported"),
        ),
        (
            "payload sha corruption",
            "UPDATE source_records SET payload_bin = X'cc'",
            "codec_invalid",
            Some("safe-json-msgpack/1"),
        ),
        (
            "safe value sha corruption",
            "UPDATE source_records SET safe_value_hash = zeroblob(32)",
            "safe_value_hash_mismatch",
            None,
        ),
    ];
    for (index, (label, sql, expected_reason, expected_codec)) in cases.iter().enumerate() {
        let (_dir, db) = db_path(&format!("e05-{index}"));
        fs::copy(&base, &db).expect("copy fixture");
        corrupt_batch(&db, sql);
        let before = file_digest(&db);
        let reader = SourceFactsReader::open(&db).expect("reader");
        let raw_error = reader
            .read_raw_source_facts(&filter, None, SourceFactsPageLimits::default())
            .expect_err(label);
        let full_error = reader
            .read_source_facts(&filter, None, SourceFactsPageLimits::default())
            .expect_err(label);
        assert_same_error(
            &full_error,
            &raw_error,
            SourceFactsReadErrorCode::DecodeFailed,
            expected_reason,
        );
        if let Some(codec) = expected_codec {
            assert_eq!(
                full_error.detail().get("codec").and_then(Json::as_str),
                Some(*codec),
                "{label}"
            );
        }
        drop(reader);
        assert_eq!(
            file_digest(&db),
            before,
            "{label}: no write from the full reader"
        );
    }
}

// ---------------------------------------------------------------------------
// e06: cursor refusals pass through unchanged
// ---------------------------------------------------------------------------

#[test]
fn e06_cursor_refusal_passthrough() {
    let (_dir, base) = db_path("e06-base");
    let sealed = b"{\"type\":\"unknown\",\"n\":1}\n{\"type\":\"unknown\",\"n\":2}\n";
    let input = verified_for("C13_E06", "claude_code", SourceFormat::Jsonl, sealed);
    let key = *input.input_key();
    let records = staged_variant(sealed, SourceFormat::Jsonl, false);
    assert_eq!(records.len(), 2);
    publish(
        &base,
        &input,
        &records,
        ProjectionDisposition::WholeInputRejected,
        TerminalState::Failed,
    );

    let filter = SourceFactsFilter {
        scope: SourceFactsScope::AllSource,
        ..Default::default()
    };
    let limits = SourceFactsPageLimits {
        max_records: 1,
        target_bytes: 8_388_608,
    };
    let reader = SourceFactsReader::open(&base).expect("reader");
    let full_first = reader
        .read_source_facts(&filter, None, limits)
        .expect("full first page");
    let raw_first = reader
        .read_raw_source_facts(&filter, None, limits)
        .expect("raw first page");
    assert_same_page(&full_first, &raw_first);
    let cursor = full_first.next_cursor.clone().expect("cursor");

    // Valid continuation control: both APIs accept the untouched cursor.
    let full_control = reader
        .read_source_facts(&filter, Some(&cursor), limits)
        .expect("full continuation");
    let raw_control = reader
        .read_raw_source_facts(&filter, Some(&cursor), limits)
        .expect("raw continuation");
    assert_same_page(&full_control, &raw_control);
    assert_eq!(full_control.records.len(), 1);
    drop(reader);

    // filter_changed
    let changed = SourceFactsFilter {
        scope: SourceFactsScope::AllSource,
        connectors: vec!["codex".into()],
        ..Default::default()
    };
    let reader = SourceFactsReader::open(&base).expect("reader");
    let full_error = reader
        .read_source_facts(&changed, Some(&cursor), limits)
        .expect_err("filter change");
    let raw_error = reader
        .read_raw_source_facts(&changed, Some(&cursor), limits)
        .expect_err("filter change");
    assert_same_error(
        &full_error,
        &raw_error,
        SourceFactsReadErrorCode::InvalidCursor,
        "filter_changed",
    );

    // malformed cursor
    let full_error = reader
        .read_source_facts(&filter, Some("not-a-cursor"), limits)
        .expect_err("malformed cursor");
    let raw_error = reader
        .read_raw_source_facts(&filter, Some("not-a-cursor"), limits)
        .expect_err("malformed cursor");
    assert_same_error(
        &full_error,
        &raw_error,
        SourceFactsReadErrorCode::InvalidCursor,
        "invalid_encoding",
    );
    drop(reader);

    // library_changed on an independent copy
    let (_lib_dir, library_db) = db_path("e06-library");
    fs::copy(&base, &library_db).expect("copy library");
    corrupt(
        &library_db,
        "INSERT OR REPLACE INTO meta(key, value) VALUES('library_identity', 'other-library')",
        &[],
    );
    let reader = SourceFactsReader::open(&library_db).expect("reader");
    let full_error = reader
        .read_source_facts(&filter, Some(&cursor), limits)
        .expect_err("library change");
    let raw_error = reader
        .read_raw_source_facts(&filter, Some(&cursor), limits)
        .expect_err("library change");
    assert_same_error(
        &full_error,
        &raw_error,
        SourceFactsReadErrorCode::StaleCursor,
        "library_changed",
    );
    drop(reader);

    // revision_changed on an independent copy: publishing another input moves
    // the facts revision while the old cursor stays behind.
    let (_rev_dir, revision_db) = db_path("e06-revision");
    fs::copy(&base, &revision_db).expect("copy revision");
    publish_empty(&revision_db, "C13_E06_EXTRA");
    let reader = SourceFactsReader::open(&revision_db).expect("reader");
    let moved = reader
        .read_source_facts(&filter, None, limits)
        .expect("fresh page");
    assert!(
        moved.source_facts_revision > full_first.source_facts_revision,
        "the extra activation moved the revision"
    );
    let full_error = reader
        .read_source_facts(&filter, Some(&cursor), limits)
        .expect_err("revision change");
    let raw_error = reader
        .read_raw_source_facts(&filter, Some(&cursor), limits)
        .expect_err("revision change");
    assert_same_error(
        &full_error,
        &raw_error,
        SourceFactsReadErrorCode::StaleCursor,
        "revision_changed",
    );
    drop(reader);

    // input_header_changed at an unchanged revision on an independent copy.
    let (_header_dir, header_db) = db_path("e06-header");
    fs::copy(&base, &header_db).expect("copy header");
    corrupt(
        &header_db,
        "UPDATE source_inputs SET observed_records = NULL, observed_blank_lines = NULL WHERE input_key = ?1",
        &[Value::Blob(key.as_bytes().to_vec())],
    );
    let reader = SourceFactsReader::open(&header_db).expect("reader");
    let fresh = reader
        .read_source_facts(&filter, None, limits)
        .expect("fresh page");
    assert_eq!(
        fresh.source_facts_revision, full_first.source_facts_revision,
        "the header update does not move the revision"
    );
    let full_error = reader
        .read_source_facts(&filter, Some(&cursor), limits)
        .expect_err("header change");
    let raw_error = reader
        .read_raw_source_facts(&filter, Some(&cursor), limits)
        .expect_err("header change");
    assert_same_error(
        &full_error,
        &raw_error,
        SourceFactsReadErrorCode::StaleCursor,
        "input_header_changed",
    );
}
